//! RAWmakase's black & white mix: the grey Camera Raw makes of each colour,
//! measured, and each band's slider on top.
//!
//! RAWmakase's chart (`rm_black_white_chart.tsv`, generated by
//! scripts/rawmakase-gray-chart.mjs from their `black_white_chart.bin`) holds
//! Camera Raw 18.7's grey for each cell of a grid of linear ProPhoto RGB, 36
//! hues by 6 saturations by 6 values: at a zero mix, and with each of the
//! eight bands at -100, -50, +50 and +100. `gray_grid` turns a mix into one
//! number per cell, log2 of the grey's luminance over the colour's, and `gray`
//! looks a colour up in it. The app's renderer runs the same lookup on the GPU
//! (`rm_gray` in src-tauri/src/shaders/modules.wgsl), from the grid this makes
//! (src-tauri/src/mods/black_white.rs).
//!
//! FROM RAWMAKASE
//!
//! RAWmakase `v0.4.0` @ a8c5d6d7 (MIT):
//! - `crates/rawmakase-engine/src/develop/black_white.rs`: `gray_grid`, `gray`,
//!   the chart's layout and scale, and the test of it,
//!   `chart_gray_follows_camera_raws_measurements`.
//! - `crates/rawmakase-engine/src/develop/gpu/develop.wgsl`: `mixer`, whose
//!   lookup `gray` follows, and `hue_of`.
//!
//! WHAT CHANGED IN THE COPY
//!
//! - Only the value change: RAWmakase's grid is the colour mixer's, with a
//!   hue and a saturation change per cell that the black & white grid leaves
//!   at zero, so the grid here is one number per cell and `gray` scales the
//!   luminance by it directly.
//! - The chart is read from text, as the repository keeps no binaries.

use std::sync::OnceLock;

/// The mix's bands, in Lightroom's and RAWmakase's order: Red, Orange,
/// Yellow, Green, Aqua, Blue, Purple, Magenta.
pub const BANDS: usize = 8;

/// The grid: 36 hues, 6 saturations, 6 values.
pub const CELLS: usize = 36 * 6 * 6;

/// Where each band was measured, in slider units.
const POSITIONS: [f32; 4] = [-1.0, -0.5, 0.5, 1.0];

/// The zero mix, then each band at each position.
const TABLES: usize = 1 + BANDS * POSITIONS.len();

/// A chart cell's unit: log2 of a luminance ratio, in steps of 1/4000.
const STEP: f32 = 1.0 / 4000.0;

// Linear sRGB to linear ProPhoto, Bradford-adapted; modules.wgsl's
// AG_SRGB_TO_PROPHOTO, row by row.
const SRGB_TO_PROPHOTO: [[f32; 3]; 3] = [
    [0.5293458, 0.3300728, 0.1405813],
    [0.0983744, 0.8734610, 0.0281647],
    [0.0168832, 0.1176725, 0.8654443],
];

/// The chart, `TABLES` tables of `CELLS`, in log2 units. Empty if it does not
/// read, which a test rules out; a mix then turns each colour into its
/// luminance.
fn chart() -> &'static [f32] {
    static CHART: OnceLock<Vec<f32>> = OnceLock::new();
    CHART.get_or_init(|| parse_chart(include_str!("rm_black_white_chart.tsv")).unwrap_or_default())
}

/// The cells of the chart's text, in the binary's order: a row is a table's
/// name, a hue, then that hue's 36 cells.
fn parse_chart(text: &str) -> Result<Vec<f32>, String> {
    let mut cells = Vec::with_capacity(TABLES * CELLS);
    for (i, line) in text.lines().enumerate() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        for field in line.split('\t').skip(2) {
            let step: i16 = field
                .parse()
                .map_err(|_| format!("rm_black_white_chart.tsv line {}: {field}", i + 1))?;
            cells.push(f32::from(step) * STEP);
        }
    }
    if cells.len() != TABLES * CELLS {
        return Err(format!(
            "rm_black_white_chart.tsv holds {} cells, not {}",
            cells.len(),
            TABLES * CELLS
        ));
    }
    Ok(cells)
}

// from RAWmakase crates/rawmakase-engine/src/develop/black_white.rs @ a8c5d6d7, `gray_grid`.
/// The grid of a mix (each band -1..1): for each cell, log2 of the grey's
/// luminance over the colour's.
pub fn gray_grid(mix: [f32; BANDS]) -> Vec<f32> {
    let chart = chart();
    if chart.is_empty() {
        return vec![0.0; CELLS];
    }
    let mut weights: Vec<(usize, f32)> = vec![(0, 1.0)];
    for (band, &v) in mix.iter().enumerate() {
        let v = v.clamp(-1.0, 1.0);
        if v == 0.0 {
            continue;
        }
        // Linear between the measured positions, and toward no change at 0.
        let (near, far) = if v < 0.0 { (1, 0) } else { (2, 3) };
        let table = |position: usize| 1 + band * POSITIONS.len() + position;
        let half = POSITIONS[near].abs();
        if v.abs() <= half {
            weights.push((table(near), v.abs() / half));
        } else {
            let t = (v.abs() - half) / (1.0 - half);
            weights.push((table(near), 1.0 - t));
            weights.push((table(far), t));
        }
    }
    (0..CELLS)
        .map(|cell| {
            weights
                .iter()
                .map(|&(table, w)| w * chart[table * CELLS + cell])
                .sum()
        })
        .collect()
}

// from RAWmakase crates/rawmakase-engine/src/develop/black_white.rs @ a8c5d6d7,
// `gray`, with the lookup of gpu/develop.wgsl's `mixer` and `hue_of`.
/// The grey `rgb` (linear sRGB) becomes under `grid`, as linear luminance.
pub fn gray(grid: &[f32], rgb: [f32; 3]) -> f32 {
    let rgb = rgb.map(|v| v.max(0.0));
    let luminance = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
    let q =
        SRGB_TO_PROPHOTO.map(|row| (row[0] * rgb[0] + row[1] * rgb[1] + row[2] * rgb[2]).max(0.0));
    let max_v = q[0].max(q[1]).max(q[2]);
    if max_v <= 1e-6 {
        return luminance;
    }
    let d = max_v - q[0].min(q[1]).min(q[2]);
    let hue = if d < 1e-9 {
        0.0
    } else if max_v == q[0] {
        ((q[1] - q[2]) / d).rem_euclid(6.0) / 6.0
    } else if max_v == q[1] {
        ((q[2] - q[0]) / d + 2.0) / 6.0
    } else {
        ((q[0] - q[1]) / d + 4.0) / 6.0
    };
    let fh = hue.rem_euclid(1.0) * 36.0 - 0.5;
    let fs = ((d / max_v).clamp(0.0, 1.0).sqrt() * 6.0 - 0.5).clamp(0.0, 5.0);
    let fv = (max_v.clamp(0.0, 1.0).powf(0.45) * 6.0 - 0.5).clamp(0.0, 5.0);
    let h0 = fh.floor();
    let (th, ts, tv) = (fh - h0, fs.fract(), fv.fract());
    let (s0, v0) = (fs as usize, fv as usize);
    let (s1, v1) = ((s0 + 1).min(5), (v0 + 1).min(5));
    let mut dv = 0.0;
    for dh in 0..2 {
        let hi = (h0 + dh as f32).rem_euclid(36.0) as usize;
        let wh = if dh == 1 { th } else { 1.0 - th };
        for (si, ws) in [(s0, 1.0 - ts), (s1, ts)] {
            for (vi, wv) in [(v0, 1.0 - tv), (v1, tv)] {
                dv += grid[(hi * 6 + si) * 6 + vi] * wh * ws * wv;
            }
        }
    }
    (luminance * dv.exp2()).max(0.0)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn luminance(rgb: [f32; 3]) -> f32 {
        0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2]
    }

    #[test]
    fn the_chart_reads_whole() {
        let chart = parse_chart(include_str!("rm_black_white_chart.tsv")).expect("the chart reads");
        assert_eq!(chart.len(), TABLES * CELLS);
        assert_eq!(super::chart().len(), TABLES * CELLS);
        assert!(parse_chart("zero\t0\t1\n").is_err());
    }

    // RAWmakase's own test of the chart, black_white.rs
    // `chart_gray_follows_camera_raws_measurements` @ a8c5d6d7, on this copy.
    #[test]
    fn chart_gray_follows_camera_raws_measurements() {
        let zero = gray_grid([0.0; BANDS]);
        // Neutrals keep their luminance; a zero mix stays near the colour's own.
        assert!((gray(&zero, [0.2; 3]) - 0.2).abs() < 0.01);
        let orange = [0.6, 0.3, 0.1];
        assert!((gray(&zero, orange) / luminance(orange) - 1.0).abs() < 0.25);
        // Camera Raw's -100 on a band takes its saturated colours to near
        // black, its +100 brightens them; positions between are between.
        let band = |v: f32| {
            let mut mix = [0.0; BANDS];
            mix[1] = v;
            gray(&gray_grid(mix), orange)
        };
        let (dark, base, light) = (band(-1.0), band(0.0), band(1.0));
        assert!(
            dark < base * 0.3 && light > base * 1.5,
            "{dark} {base} {light}"
        );
        assert!(band(-0.75) < band(-0.5) && band(-0.5) < base);
        assert!(band(0.25) > base && band(0.25) < band(0.5));
        // No band moves a grey, as in Camera Raw.
        for b in 0..BANDS {
            for v in [-1.0, 1.0] {
                let mut mix = [0.0; BANDS];
                mix[b] = v;
                let moved = gray(&gray_grid(mix), [0.2; 3]);
                assert!(
                    (moved - gray(&zero, [0.2; 3])).abs() < 1e-5,
                    "{b} {v} {moved}"
                );
            }
        }
    }

    /// Black stays black and a band's slider outside -1..1 is held at its end.
    #[test]
    fn black_and_out_of_range_mixes_are_safe() {
        let grid = gray_grid([0.0; BANDS]);
        assert_eq!(gray(&grid, [0.0; 3]), 0.0);
        assert_eq!(gray(&grid, [-0.1, 0.0, -0.2]), 0.0);
        assert_eq!(gray_grid([2.0; BANDS]), gray_grid([1.0; BANDS]));
    }
}
